method intersection(interval1: (int, int), interval2: (int, int)) returns (result: string)
    requires interval1.1 >= interval1.0
    requires interval2.1 >= interval2.0
    requires interval1.0 <= interval1.1
    requires interval2.0 <= interval2.1
    ensures result == "YES" ==> lengthOfIntersectionIsPrime(interval1, interval2)
    ensures result == "NO" ==> lengthOfIntersectionIsNotPrime(interval1, interval2)
    ensures result == "NO" ==> not intersects(interval1, interval2)

    // Helper function to check if the length of the intersection is prime
    predicate lengthOfIntersectionIsPrime(i1: (int, int), i2: (int, int)) {
        var start = max(i1.0, i2.0);
        var end = min(i1.1, i2.1);
        start < end && isPrime(end - start)
    }

    // Helper function to check if the length of the intersection is not prime
    predicate lengthOfIntersectionIsNotPrime(i1: (int, int), i2: (int, int)) {
        var start = max(i1.0, i2.0);
        var end = min(i1.1, i2.1);
        start < end ==> !isPrime(end - start)
    }

    // Helper function to check if intervals intersect
    predicate intersects(i1: (int, int), i2: (int, int)) {
        max(i1.0, i2.0) <= min(i1.1, i2.1)
    }

    // Helper function to determine if a number is prime
    predicate isPrime(n: int) {
        n > 1 && forall k: int :: (1 < k < n) ==> n % k != 0
    }
